3	/**
4	 * Shared telephone normalization for the create-owner pipeline: strip every non-digit
5	 * character. Used both by {@link NormalizeOwnerTelephone} (which then requires exactly
6	 * ten digits) and by {@link EnsureUniqueTelephone} (which normalizes each stored
7	 * telephone before comparing), so the two steps agree on what "normalized" means.
8	 */
9	final class TelephoneNormalizer {
10	
11	    private TelephoneNormalizer() {
12	    }
13	
14	    static String normalize(String telephone) {
15	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
16	    }
17	}
