1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes the create-owner telephone by stripping every non-digit character, then
9	 * requires exactly ten digits. Runs after {@link ValidateOwnerFields} (so the field
10	 * is known to be present) and before {@link BuildOwner}, mutating the published
11	 * {@link OwnerFieldsDto} in place so the owner is built and stored with the ten-digit
12	 * value. A non-conforming number is rejected as a 400 via
13	 * {@link InvalidTelephoneException}.
14	 */
15	public class NormalizeOwnerTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
18	        String digits = TelephoneNormalizer.normalize(request.getTelephone());
19	        if (digits.length() != 10) {
20	            throw new InvalidTelephoneException(request.getTelephone());
21	        }
22	        request.setTelephone(digits);
23	    }
24	}
