1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Rejects a create request whose normalized telephone is already used by an existing
11	 * owner. Runs after {@link NormalizeOwnerTelephone} (so the request telephone is the
12	 * ten-digit normalized value) and before {@link BuildOwner}, so a collision is a 409
13	 * via {@link DuplicateTelephoneException} before any owner is built or saved. Each
14	 * stored telephone is normalized the same way before comparing.
15	 */
16	public class EnsureUniqueTelephone {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateTelephoneException {
20	        String telephone = request.getTelephone();
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (telephone.equals(TelephoneNormalizer.normalize(existing.getTelephone()))) {
23	                throw new DuplicateTelephoneException(telephone);
24	            }
25	        }
26	    }
27	}
